function OtpForgePure(){
  // ---- 纯 JS SHA-1（字节数组 -> 字节数组）----
  function sha1(msg){
    function rotl(x,n){return (x<<n)|(x>>>(32-n));}
    var H=[0x67452301,0xEFCDAB89,0x98BADCFE,0x10325476,0xC3D2E1F0];
    var m=msg.slice();
    var bitLen=m.length*8;
    m.push(0x80);
    while(m.length%64!==56) m.push(0);
    for(var s=7;s>=0;s--){ m.push((bitLen/Math.pow(2,8*s))&0xff); }
    for(var i=0;i<m.length;i+=64){
      var w=new Array(80);
      for(var t=0;t<16;t++){ w[t]=(m[i+t*4]<<24)|(m[i+t*4+1]<<16)|(m[i+t*4+2]<<8)|(m[i+t*4+3]); }
      for(var t=16;t<80;t++){ w[t]=rotl(w[t-3]^w[t-8]^w[t-14]^w[t-16],1); }
      var a=H[0],b=H[1],c=H[2],d=H[3],e=H[4];
      for(var t=0;t<80;t++){
        var f,k;
        if(t<20){f=(b&c)|((~b)&d);k=0x5A827999;}
        else if(t<40){f=b^c^d;k=0x6ED9EBA1;}
        else if(t<60){f=(b&c)|(b&d)|(c&d);k=0x8F1BBCDC;}
        else {f=b^c^d;k=0xCA62C1D6;}
        var tmp=(rotl(a,5)+f+e+k+w[t])>>>0;
        e=d;d=c;c=rotl(b,30)>>>0;b=a;a=tmp;
      }
      H[0]=(H[0]+a)>>>0;H[1]=(H[1]+b)>>>0;H[2]=(H[2]+c)>>>0;H[3]=(H[3]+d)>>>0;H[4]=(H[4]+e)>>>0;
    }
    var out=[];
    for(var i=0;i<5;i++){ out.push((H[i]>>>24)&0xff,(H[i]>>>16)&0xff,(H[i]>>>8)&0xff,H[i]&0xff); }
    return out;
  }
  // ---- HMAC-SHA1 ----
  function hmacSha1(key, msg){
    var block=64;
    if(key.length>block){ key=sha1(key); }
    var k=new Array(block); for(var i=0;i<block;i++) k[i]=(i<key.length?key[i]:0);
    var ipad=new Array(block), opad=new Array(block);
    for(var i=0;i<block;i++){ ipad[i]=k[i]^0x36; opad[i]=k[i]^0x5c; }
    var inner=ipad.concat(msg);
    return sha1(opad.concat(sha1(inner)));
  }
  // ---- Base32 (RFC 4648) ----
  var B32='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
  function b32decode(s){
    s=(s||'').toUpperCase().replace(/=+$/,'').replace(/[^A-Z2-7]/g,'');
    if(!s) return [];
    var bits=0,value=0,out=[];
    for(var i=0;i<s.length;i++){
      var v=B32.indexOf(s[i]); if(v<0) continue;
      value=(value<<5)|v; bits+=5;
      if(bits>=8){ bits-=8; out.push((value>>bits)&0xff); }
    }
    return out;
  }
  function b32encode(bytes){
    var bits=0,value=0,out='';
    for(var i=0;i<bytes.length;i++){
      value=(value<<8)|bytes[i]; bits+=8;
      while(bits>=5){ bits-=5; out+=B32[(value>>bits)&0x1f]; }
    }
    if(bits>0){ out+=B32[(value<<(5-bits))&0x1f]; }
    while(out.length%8!==0) out+='=';
    return out;
  }
  // ---- HOTP / TOTP ----
  function hotp(keyBytes, counter, digits){
    var msg=[];
    for(var i=7;i>=0;i--){ msg.push(Math.floor(counter / Math.pow(2, 8*i)) & 0xff); }
    var hs=hmacSha1(keyBytes, msg);
    var off=hs[19]&0x0f;
    var bin=((hs[off]&0x7f)<<24)|((hs[off+1]&0xff)<<16)|((hs[off+2]&0xff)<<8)|(hs[off+3]&0xff);
    var code=(bin%Math.pow(10,digits)).toString();
    while(code.length<digits) code='0'+code;
    return code;
  }
  function totp(keyBytes, time, digits, period){
    period=period||30; digits=digits||6;
    return hotp(keyBytes, Math.floor(time/period), digits);
  }
  function parseOtpauth(uri){
    if(uri.indexOf('otpauth://')!==0) return null;
    var m=uri.match(/^otpauth:\/\/([^/]+)\/([^?]+)(\?.*)?$/);
    if(!m) return null;
    var type=m[1].toLowerCase();
    var label=decodeURIComponent(m[2].replace(/\+/g,' '));
    var issuer=null, secret=null, alg='SHA1', digits=6, period=30, counter=0;
    if(m[3]){
      m[3].slice(1).split('&').forEach(function(p){
        var kv=p.split('=');
        var k=decodeURIComponent(kv[0]); var v=kv[1]!==undefined?decodeURIComponent(kv[1].replace(/\+/g,' ')):'';
        if(k==='secret') secret=v;
        else if(k==='issuer') issuer=v;
        else if(k==='algorithm') alg=v.toUpperCase();
        else if(k==='digits') digits=parseInt(v,10)||6;
        else if(k==='period') period=parseInt(v,10)||30;
        else if(k==='counter') counter=parseInt(v,10)||0;
      });
    }
    return {type:type, label:label, issuer:issuer, secret:secret, algorithm:alg, digits:digits, period:period, counter:counter};
  }
  function analyze(input, opts){
    opts=opts||{};
    var s=(input||'').trim();
    if(!s) return {error:'请输入 Base32 密钥或 otpauth:// URI'};
    var type='totp', label=null, issuer=null, digits=opts.digits||6, period=opts.period||30, counter=0, keyBytes=null;
    if(s.indexOf('otpauth://')===0){
      var p=parseOtpauth(s);
      if(!p) return {error:'无法解析 otpauth URI'};
      if(!p.secret) return {error:'otpauth URI 缺少 secret 参数'};
      keyBytes=b32decode(p.secret);
      type=p.type; label=p.label; issuer=p.issuer; digits=p.digits;
      if(type==='hotp'){ counter=p.counter; }
      else { period=p.period; }
    } else {
      keyBytes=b32decode(s);
      if(opts.digits) digits=opts.digits;
      if(opts.period) period=opts.period;
    }
    if(!keyBytes || !keyBytes.length) return {error:'密钥解码失败（应为 Base32：A-Z 与 2-7）'};
    if(type==='hotp'){
      var code=hotp(keyBytes, counter, digits);
      return {error:null, type:type, label:label, issuer:issuer, digits:digits,
              current:{code:code, counter:counter}, remaining:null, algorithm:'SHA1'};
    }
    var now=Math.floor(Date.now()/1000);
    var c=Math.floor(now/period);
    function at(cc){ return hotp(keyBytes, cc, digits); }
    var window=[-1,0,1].map(function(d){ return {counter:c+d, code:at(c+d)}; });
    return {error:null, type:type, label:label, issuer:issuer, digits:digits, period:period,
            current:{code:at(c), counter:c}, window:window,
            remaining:period-(now%period), now:now, algorithm:'SHA1'};
  }
  var api={sha1:sha1, hmacSha1:hmacSha1, b32decode:b32decode, b32encode:b32encode,
           hotp:hotp, totp:totp, parseOtpauth:parseOtpauth, analyze:analyze};
  if(typeof window!=='undefined'){ window.__PURE__=api; }
  if(typeof module!=='undefined'&&module.exports){ module.exports={OtpForgePure:OtpForgePure}; }
  return api;
}
